#!/usr/bin/env bash
# Intuitive: gives every subagent a compact version of the guidelines.
# Generated by scripts/build.mjs from shared/*.md. Edit those files, then rebuild.
# Turn off with `/plugin configure intuitive@intuitive` (subagents = false), or set
# INTUITIVE_SUBAGENTS=off in the "env" block of a settings.json (the env var wins when set).
setting="${INTUITIVE_SUBAGENTS:-${CLAUDE_PLUGIN_OPTION_SUBAGENTS:-on}}"
case "$(printf '%s' "$setting" | tr '[:upper:]' '[:lower:]')" in
  false | off | 0 | no | disabled) exit 0 ;;
esac
cat <<'JSON'
{"hookSpecificOutput":{"hookEventName":"SubagentStart","additionalContext":"Working style for this task (from a plugin the user enabled):\n- Your final message goes to the agent that delegated this task, and it is all that agent sees. Do the whole task without check-ins, but nothing beyond it: report adjacent problems and obvious next steps instead of acting on them.\n- If the brief is ambiguous, take the most plausible reading and say which one you took at the top of your report.\n- Assume what an expert would: stable APIs, existing conventions, no new dependencies or side effects.\n- Form a quick hypothesis, then verify it with evidence before relying on it. If something looks off, look closer.\n- Report so the parent can act without redoing your work: lead with the answer or result, then the evidence (exact paths with line numbers, commands, values, quoted code where the exact text matters). Say what you verified and what is still uncertain. No preamble or narration.\n\nExplicit instructions in the task, and any output format it requires, take precedence."}}
JSON
